const { createHmac, timingSafeEqual } = require('crypto');
const input = $input.first();
const headers = input.json.headers ?? {};
const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
const secret = $env.OPSHUB_WEBHOOK_SIGNING_SECRET;

function fail(code) { throw new Error(code); }
function header(name) {
  const value = headers[name] ?? headers[name.toLowerCase()];
  if (typeof value !== 'string' || value.length === 0) fail('missing_signature_header');
  return value;
}
function isRecord(value) { return typeof value === 'object' && value !== null && !Array.isArray(value); }
function hasExactKeys(value, keys) {
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
}
function isNullableString(value) { return value === null || typeof value === 'string'; }
function isIsoDateTime(value) { return typeof value === 'string' && !Number.isNaN(Date.parse(value)); }

if (typeof secret !== 'string' || secret.length < 32) fail('receiver_not_configured');
const eventId = header('x-opshub-event-id');
const timestamp = header('x-opshub-timestamp');
const suppliedSignature = header('x-opshub-signature');
header('idempotency-key');
if (!/^\d+$/.test(timestamp)) fail('invalid_timestamp');
const timestampSeconds = Number(timestamp);
if (!Number.isSafeInteger(timestampSeconds) || Math.abs(Math.floor(Date.now() / 1000) - timestampSeconds) > 300) fail('stale_timestamp');
if (!/^v1=[0-9a-f]{64}$/.test(suppliedSignature)) fail('invalid_signature');
const expectedSignature = 'v1=' + createHmac('sha256', secret).update(timestamp, 'utf8').update('.', 'utf8').update(rawBody).digest('hex');
const suppliedBytes = Buffer.from(suppliedSignature, 'utf8');
const expectedBytes = Buffer.from(expectedSignature, 'utf8');
if (suppliedBytes.length !== expectedBytes.length || !timingSafeEqual(suppliedBytes, expectedBytes)) fail('invalid_signature');

let event;
try { event = JSON.parse(rawBody.toString('utf8')); } catch { fail('invalid_json'); }
const topKeys = ['event_id', 'event_type', 'event_version', 'occurred_at', 'request'];
const requestKeys = ['reference', 'submitted_at', 'approved_at', 'submitted_locale', 'requester_type', 'contact_name', 'email', 'phone_e164', 'country_code', 'preferred_contact_method', 'company_name', 'job_title', 'company_website', 'service_category', 'request_title', 'description', 'desired_start_date'];
if (!isRecord(event) || !hasExactKeys(event, topKeys) || !isRecord(event.request) || !hasExactKeys(event.request, requestKeys)) fail('invalid_event');
const request = event.request;
const valid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(event.event_id)
  && event.event_type === 'request.approved'
  && event.event_version === 1
  && isIsoDateTime(event.occurred_at)
  && /^[0-9A-HJKMNP-TV-Z]{10}$/.test(request.reference)
  && isIsoDateTime(request.submitted_at)
  && isIsoDateTime(request.approved_at)
  && ['ar', 'en'].includes(request.submitted_locale)
  && ['individual', 'company'].includes(request.requester_type)
  && typeof request.contact_name === 'string' && request.contact_name.length > 0
  && typeof request.email === 'string' && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(request.email)
  && typeof request.phone_e164 === 'string' && /^\+[1-9]\d{6,14}$/.test(request.phone_e164)
  && typeof request.country_code === 'string' && /^[A-Z]{2}$/.test(request.country_code)
  && (request.preferred_contact_method === null || ['email', 'phone'].includes(request.preferred_contact_method))
  && isNullableString(request.company_name)
  && isNullableString(request.job_title)
  && isNullableString(request.company_website)
  && ['consulting', 'it_software', 'marketing', 'training', 'support_maintenance', 'other'].includes(request.service_category)
  && typeof request.request_title === 'string' && request.request_title.length > 0
  && typeof request.description === 'string' && request.description.length > 0
  && (request.desired_start_date === null || /^\d{4}-\d{2}-\d{2}$/.test(request.desired_start_date));
if (!valid) fail('invalid_event');
if (event.event_id !== eventId) fail('event_id_mismatch');
return [{ json: event }];
